function canPermutePalindrome(s) {
  const counts = new Array(26).fill(0);
  for (let i = 0; i < s.length; i++) {
    counts[s.charCodeAt(i) - 97]++;
  }

  let odd = 0;
  for (const count of counts) {
    if (count % 2 === 1) {
      odd++;
    }
  }
  return odd <= 1;
}

