function canPermutePalindrome(s) {
  // Sort the letters, then pair equal neighbours; at most one letter may be left without a partner.
  const sorted = s.split('').sort();
  let unpaired = 0;
  let i = 0;
  while (i < sorted.length) {
    if (i + 1 < sorted.length && sorted[i] === sorted[i + 1]) i += 2;
    else { unpaired++; i += 1; }
  }
  return unpaired <= 1;
}

