function generate(rand, size) {
  const n = size === 'large' ? 4000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 9);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, size === 'large' ? 26 : 1 + Math.floor(rand() * 4));
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const chars = [];
  if (rand() < 0.5) {
    // Build a rearranged palindrome: mirrored pairs plus at most one middle letter.
    while (chars.length + 2 <= n) { const c = letter(); chars.push(c, c); }
    if (chars.length < n) chars.push(letter());
    // Sometimes break it by changing one letter.
    if (rand() < 0.3 && alphabet.length > 1) chars[Math.floor(rand() * chars.length)] = letter();
  } else {
    while (chars.length < n) chars.push(letter());
  }
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
